CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(80) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leads (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, email VARCHAR(190), phone VARCHAR(40), company VARCHAR(180), source VARCHAR(80), owner_id BIGINT, status VARCHAR(50) NOT NULL, priority VARCHAR(30), notes TEXT, follow_up_at DATETIME, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE pipeline_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, lead_id BIGINT NOT NULL, from_status VARCHAR(50), to_status VARCHAR(50) NOT NULL, changed_by BIGINT NOT NULL, changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (lead_id) REFERENCES leads(id), FOREIGN KEY (changed_by) REFERENCES users(id));
CREATE TABLE tasks (id BIGINT PRIMARY KEY AUTO_INCREMENT, lead_id BIGINT, title VARCHAR(180) NOT NULL, due_at DATETIME, priority VARCHAR(30), completed_at DATETIME NULL, assigned_to BIGINT, FOREIGN KEY (lead_id) REFERENCES leads(id), FOREIGN KEY (assigned_to) REFERENCES users(id));
CREATE TABLE customers (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180) NOT NULL, company VARCHAR(180), email VARCHAR(190), notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
